<?php

namespace Database\Factories;

use App\Enums\CashMovementDirection;
use App\Enums\CashMovementType;
use App\Enums\PaymentMethod;
use App\Models\CashMovement;
use App\Models\Payment;
use App\Models\User;
use Illuminate\Database\Eloquent\Factories\Factory;

/**
 * Defaults to the movement generated by a cash payment.
 *
 * @extends Factory<CashMovement>
 */
class CashMovementFactory extends Factory
{
    /**
     * Define the model's default state.
     *
     * @return array<string, mixed>
     */
    public function definition(): array
    {
        return [
            'source_type' => 'payment',
            'source_id' => Payment::factory(),
            'cash_session_id' => fn (array $attributes) => Payment::find($attributes['source_id'])->cash_session_id,
            'performed_by' => User::factory(),
            'movement_type' => CashMovementType::Payment,
            'payment_method' => PaymentMethod::Cash,
            'direction' => CashMovementDirection::In,
            'amount' => fn (array $attributes) => Payment::find($attributes['source_id'])->amount,
            'affects_cash' => true,
            'operation_uuid' => fn (array $attributes) => Payment::find($attributes['source_id'])->operation_uuid,
            'description' => 'Cobro de estadía',
            'occurred_at' => now(),
        ];
    }
}
